function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  stroke("#e08a72");
  strokeWeight(1);
  fill("#e08a72", 100);
  brush.fillBleed(0.2);
  brush.fillTexture(0.5, false);
  brush.fillBleed(1);
  brush.fillTexture(0, true);
  brush.beginShape();
  vertex(0, 0);     // top left
  vertex(400, 0);   // top right
  vertex(200, 200); // middle
  vertex(0, 400);   // bottom left
  vertex(400, 400); // bottom right
  vertex(200, 200); // back to start
  brush.endShape(true);
  stroke(10);
  line(0, 0, 400, 0);
  line(0, 400, 400, 400);
  line(0, 0, 0, 400);
  line(400, 0, 400, 400);
  line(0, 0, 200, 200);
  line(400, 0, 200, 200);
  line(0, 400, 200, 200);
  line(400, 400, 200, 200);
}
