  for (let i = 0; i < 50; i++) {
    let x = random(0, 200);
    let y = random(0, 400);
    if (random() < 0.3) {
      line(x, y, x + 5, y);
    } else {
      line(x, y, x, y + 5);
    }
  }
  fill("#c1a288");
  brush.strokeWeight(4);
  for (let i = 0; i < 20; i++) {
    let x = random(0, 200);
    let y = random(0, 400);
    let s = random(3, 15);
    let i = random(4, 16);
    brush.vertex(x, y, s, i);
  }
  brush.stroke("#8d7b6c");
  strokeWeight(1);
}

